// Body, head and pose sprites. Rows are generated by small helpers but exported as plain strings.
const grid = (w, h) => Array.from({ length: h }, () => Array(w).fill('.'));
const put = (g, x, y, c) => { if (y >= 0 && y < g.length && x >= 0 && x < g[0].length) g[y][x] = c; };
const rect = (g, x0, y0, x1, y1, c) => { for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) put(g, x, y, c); };
const rows = (g) => g.map((r) => r.join(''));
const spr = (w, h, r) => ({ w, h, rows: r });

// Leg: 2 wide, L rows 20 to 21 (minus lift), shoe row, outline row.
const leg = (g, x, lift = 0, shoe = 0) => {
  const b = 21 - lift;
  rect(g, x - 1, 20, x - 1, b + 1, 'O');
  rect(g, x + 2, 20, x + 2, b + 1, 'O');
  rect(g, x, 20, x + 1, b, 'L');
  rect(g, x + shoe, b + 1, x + 1, b + 1, 'd');
  if (shoe < 0) put(g, x + shoe - 1, b + 1, 'O');
  rect(g, Math.min(x, x + shoe) - (shoe < 0 ? 1 : 0), b + 2, x + 2, b + 2, 'O');
};

// Hanging arm, 2 wide, from y 15 to y1 with hand.
const arm = (g, x, y1) => {
  rect(g, x - 1, 15, x - 1, y1 + 1, 'O');
  rect(g, x + 2, 15, x + 2, y1 + 1, 'O');
  rect(g, x, 15, x + 1, y1, '1');
  rect(g, x, y1, x + 1, y1, '2');
  rect(g, x, y1 + 1, x + 1, y1 + 1, 'O');
};

// Torso: front or back, x 4 to 11.
const torso = (g, back, chest = 0) => {
  rect(g, 4, 14, 11, 14, 'O');
  rect(g, 4, 15, 4, 19, 'O');
  rect(g, 11, 15, 11, 19, 'O');
  rect(g, 5, 15, 10, 17, '2');
  rect(g, 5, 15, 5, 17, '1');
  rect(g, 10, 15, 10, 17, '3');
  rect(g, 5, 18, 10, 19, 'L');
  if (back) rect(g, 7, 15, 8, 16, '3');
  else if (chest) rect(g, 6, 16, 9, 16, '1');
};

const front = (o = {}) => {
  const g = grid(16, 24);
  const back = o.view === 'u';
  arm(g, 2, o.al ?? 19);
  arm(g, 12, o.ar ?? 19);
  torso(g, back, o.chest);
  leg(g, 5, o.ll || 0);
  leg(g, 9, o.lr || 0);
  if (o.extra) o.extra(g);
  return g;
};

// Side view facing left (profile). Torso x 6 to 9.
const side = (o = {}) => {
  const g = grid(16, 24);
  rect(g, 6, 14, 9, 14, 'O');
  rect(g, 5, 15, 5, 19, 'O');
  rect(g, 10, 15, 10, 19, 'O');
  rect(g, 6, 15, 9, 17, '2');
  rect(g, 9, 15, 9, 17, '3');
  rect(g, 6, 18, 9, 19, 'L');
  const back = o.back || [8, 0];
  const frontLeg = o.fl || [5, 0, -1];
  // back leg first, front leg over it
  leg(g, back[0], back[1], -1);
  leg(g, frontLeg[0], frontLeg[1], frontLeg[2]);
  // back arm (behind torso), then front arm
  if (o.ab) { rect(g, o.ab - 1, 15, o.ab - 1, 18, 'O'); rect(g, o.ab, 15, o.ab + 1, 17, '3'); rect(g, o.ab + 2, 15, o.ab + 2, 18, 'O'); rect(g, o.ab, 18, o.ab + 1, 18, 'O'); }
  const ax = o.af ?? 6;
  const ay = o.afy ?? 18;
  rect(g, ax - 1, 15, ax - 1, ay + 1, 'O');
  rect(g, ax + 2, 15, ax + 2, ay + 1, 'O');
  rect(g, ax, 15, ax + 1, ay, '1');
  rect(g, ax, ay, ax + 1, ay, '2');
  rect(g, ax, ay + 1, ax + 1, ay + 1, 'O');
  return g;
};

// Arm raised straight up on the left (x 1) or right (x 14) edge.
const up = (g, left, top) => {
  const sx = left ? 1 : 14;
  const o1 = left ? 0 : 15;
  const o2 = left ? 2 : 13;
  rect(g, o1, top, o1, 16, 'O');
  rect(g, o2, 14, o2, 14, 'O');
  rect(g, sx, top, sx, 16, '1');
  rect(g, sx, top, sx, top + 1, '2');
  put(g, sx, top - 1, 'O');
  put(g, o1, top - 1, 'O');
  // shoulder link
  const xs = left ? [2, 3] : [12, 13];
  rect(g, xs[0], 15, xs[1], 16, '1');
  rect(g, xs[0], 17, xs[1], 17, 'O');
  put(g, left ? 1 : 14, 17, 'O');
  put(g, left ? 0 : 15, 17, 'O');
};

const S = {};
const A = {};
const add = (id, g, w = 16, h = 24) => { S[id] = spr(w, h, rows(g)); };

S['shadow'] = spr(12, 3, ['..kkkkkkkk..', '.kkkkkkkkkk.', '..kkkkkkkk..']);

S['head.d'] = spr(12, 11, [
  '..OOOOOOOO..',
  '.O11111111O.',
  'O1111111112O',
  'O1111111112O',
  'O11E1111E12O',
  'O11E1111E12O',
  'OBB111111BBO',
  'O1111331112O',
  '.O11111112O.',
  '..O111112O..',
  '...OOOOOO...',
]);
S['head.u'] = spr(12, 11, [
  '..OOOOOOOO..',
  '.O11111111O.',
  'O1111111112O',
  'O1111111112O',
  'O1111111112O',
  'O1111111122O',
  'O1111111122O',
  'O1111111122O',
  '.O11111122O.',
  '..O112222O..',
  '...OOOOOO...',
]);
S['head.l'] = spr(12, 11, [
  '..OOOOOOOO..',
  '.O11111111O.',
  'O1111111112O',
  'O1111111122O',
  'O1E11111122O',
  'O1E11111122O',
  'OB111111122O',
  'O3111111122O',
  '.O11111122O.',
  '..O111122O..',
  '...OOOOOO...',
]);

// Walk
add('body.walk.d.0', front({ view: 'd' }));
add('body.walk.d.1', front({ view: 'd', ll: 1, al: 17, ar: 20 }));
add('body.walk.d.2', front({ view: 'd' }));
add('body.walk.d.3', front({ view: 'd', lr: 1, al: 20, ar: 17 }));
add('body.walk.u.0', front({ view: 'u' }));
add('body.walk.u.1', front({ view: 'u', ll: 1, al: 17, ar: 20 }));
add('body.walk.u.2', front({ view: 'u' }));
add('body.walk.u.3', front({ view: 'u', lr: 1, al: 20, ar: 17 }));
add('body.walk.l.0', side({ back: [8, 0], fl: [5, 0, -1], af: 6, afy: 18 }));
add('body.walk.l.1', side({ back: [9, 1], fl: [3, 0, -1], af: 3, afy: 18, ab: 9 }));
add('body.walk.l.2', side({ back: [8, 0], fl: [5, 0, -1], af: 6, afy: 18 }));
add('body.walk.l.3', side({ back: [3, 0], fl: [9, 1, -1], af: 9, afy: 17, ab: 3 }));

// Idle
add('body.idle.d.0', front({ view: 'd' }));
add('body.idle.d.1', front({ view: 'd', al: 18, ar: 18, chest: 1 }));

// Seated study (facing down, at a desk): forearms forward on the desk, writing hand moves.
const study = (hx, hy) => front({
  view: 'd', al: 17, ar: 17,
  extra: (g) => {
    // forearms folded to centre
    rect(g, 3, 18, 12, 18, 'O');
    rect(g, 3, 19, 12, 19, '1');
    rect(g, 3, 20, 12, 20, 'O');
    rect(g, hx, hy, hx + 1, hy, '2');
  },
});
add('body.sit_study.0', study(6, 19));
add('body.sit_study.1', study(7, 19));
add('body.sit_study.2', study(8, 19));

// Break: cup held at chest, raised to sip, stretch.
add('body.break.0', front({
  view: 'd', ar: 17,
  extra: (g) => { rect(g, 11, 15, 14, 16, '1'); rect(g, 10, 17, 14, 17, 'O'); rect(g, 12, 16, 13, 16, '2'); },
}));
add('body.break.1', front({
  view: 'd', ar: 17,
  extra: (g) => { rect(g, 11, 14, 13, 15, '1'); rect(g, 10, 16, 13, 16, 'O'); put(g, 13, 14, '2'); },
}));
add('body.break.2', front({
  view: 'd', al: 16, ar: 16,
  extra: (g) => { up(g, true, 7); up(g, false, 7); },
}));

// Cheer: arms up, jump
add('body.cheer.0', front({ view: 'd', al: 14, ar: 14, extra: (g) => { up(g, true, 6); up(g, false, 6); } }));
add('body.cheer.1', front({ view: 'd', al: 14, ar: 14, ll: 2, lr: 2, extra: (g) => { up(g, true, 4); up(g, false, 4); } }));
add('body.cheer.2', front({ view: 'd', al: 14, ar: 14, ll: 2, lr: 2, extra: (g) => { up(g, true, 5); up(g, false, 5); } }));
add('body.cheer.3', front({ view: 'd', al: 14, ar: 14, extra: (g) => { up(g, true, 7); up(g, false, 7); } }));

// Knock (facing up, toward a door): right fist raised, then taps.
add('body.knock.0', front({ view: 'u', ar: 14, extra: (g) => up(g, false, 6) }));
add('body.knock.1', front({ view: 'u', ar: 14, extra: (g) => up(g, false, 9) }));
add('body.knock.2', front({ view: 'u', ar: 14, extra: (g) => up(g, false, 7) }));

S['prop.cup'] = spr(8, 8, [
  '........',
  '..OOOO..',
  '.OWWWWO.',
  '.OaaaaOO',
  '.OaaaaOO',
  '.OaaaaO.',
  '..OOOO..',
  '........',
]);
S['prop.pencil'] = spr(8, 8, [
  '......OO',
  '.....OnO',
  '....OnO.',
  '...OcO..',
  '..OcO...',
  '.OdO....',
  '.OO.....',
  '........',
]);

const fr = (b, hy, ty, prop, hx = 0, tx = 0) => {
  const f = { body: b, sprite: b, hx, hy, tx, ty };
  if (prop) f.prop = prop;
  return f;
};
const walk = (v) => ({
  id: `walk.${v}`, fps: 8, loop: true,
  frames: [0, 1, 2, 3].map((i) => fr(`body.walk.${v}.${i}`, i % 2 ? -1 : 0, i % 2 ? -1 : 0)),
});
A['walk.d'] = walk('d');
A['walk.u'] = walk('u');
A['walk.l'] = walk('l');
A['idle.d'] = { id: 'idle.d', fps: 2, loop: true, frames: [fr('body.idle.d.0', 0, 0), fr('body.idle.d.1', 1, 1)] };
A['sit_study'] = {
  id: 'sit_study', fps: 4, loop: true,
  frames: [
    fr('body.sit_study.0', 2, 2, { id: 'prop.pencil', x: 6, y: 13 }),
    fr('body.sit_study.1', 3, 2, { id: 'prop.pencil', x: 7, y: 13 }),
    fr('body.sit_study.2', 2, 2, { id: 'prop.pencil', x: 8, y: 13 }),
  ],
};
A['break'] = {
  id: 'break', fps: 3, loop: true,
  frames: [
    fr('body.break.0', 0, 0, { id: 'prop.cup', x: 10, y: 8 }),
    fr('body.break.1', 0, 0, { id: 'prop.cup', x: 9, y: 5 }),
    fr('body.break.2', -1, -1),
  ],
};
A['cheer'] = {
  id: 'cheer', fps: 6, loop: true,
  frames: [fr('body.cheer.0', 0, 0), fr('body.cheer.1', -2, -2), fr('body.cheer.2', -2, -2), fr('body.cheer.3', 0, 0)],
};
A['knock'] = {
  id: 'knock', fps: 4, loop: true,
  frames: [fr('body.knock.0', 0, 0), fr('body.knock.1', 1, 1), fr('body.knock.2', 0, 0)],
};

export default { sprites: S, anims: A, meta: { skinTones: 6 } };
